    "content": "import { io, Socket } from 'socket.io-client'

const WS_URL = import.meta.env.VITE_WS_URL || ''

class WebSocketClient {
  private socket: Socket | null = null
  private listeners: Map<string, Set<(data: unknown) => void>> = new Map()

  connect(): Socket {
    if (!this.socket?.connected) {
      this.socket = io(WS_URL, {
        transports: ['websocket', 'polling'],
        autoConnect: true,
      })

      this.socket.on('connect', () => {
        console.log('[WebSocket] Connected:', this.socket?.id)
      })

      this.socket.on('disconnect', (reason) => {
        console.log('[WebSocket] Disconnected:', reason)
      })

      this.socket.on('*', (event: { type: string; data: unknown }) => {
        this.notifyListeners(event.type, event.data)
      })

      // Listen for all dashboard events
      this.socket.onAny((event: string, data: unknown) => {
        this.notifyListeners(event, data)
      })
    }
    return this.socket
  }

  disconnect(): void {
    if (this.socket) {
      this.socket.disconnect()
      this.socket = null
    }
  }

  subscribe(event: string, callback: (data: unknown) => void): () => void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set())
    }
    this.listeners.get(event)!.add(callback)

    // Return unsubscribe function
    return () => {
      this.listeners.get(event)?.delete(callback)
    }
  }

  private notifyListeners(event: string, data: unknown): void {
    this.listeners.get(event)?.forEach((cb) => cb(data))
    // Also notify wildcard listeners
    this.listeners.get('*')?.forEach((cb) => cb({ event, data }))
  }

  /** Subscribe to a specific run's WebSocket channel */
  joinRunRoom(runId: number): void {
    this.socket?.emit('join', `run:${runId}`)
  }

  /** Unsubscribe from a run's WebSocket channel */
  leaveRunRoom(runId: number): void {
    this.socket?.emit('leave', `run:${runId}`)
  }

  /** Subscribe to dashboard broadcasts */
  joinDashboard(): void {
    this.socket?.emit('join', 'dashboard')
  }

  /** Subscribe to experiment updates */
  joinExperiment(experimentId: number): void {
    this.socket?.emit('join', `experiment:${experimentId}`)
  }
}

export const wsClient = new WebSocketClient()

// Convenience hooks for common subscriptions
export function useRunWebSocket(runId: number, onEvent: (type: string, data: unknown) => void): () => void {
  const client = wsClient.connect()
  client.emit('join', `run:${runId}`)

  const handlers: Array<[string, (data: unknown) => void]> = [
    [`run:${runId}:started`, (data) => onEvent('run.started', data)],
    [`run:${runId}:step.started`, (data) => onEvent('run.step.started', data)],
    [`run:${runId}:step.completed`, (data) => onEvent('run.step.completed', data)],
    [`run:${runId}:log`, (data) => onEvent('run.log', data)],
    [`run:${runId}:metric`, (data) => onEvent('run.metric', data)],
    [`run:${runId}:completed`, (data) => onEvent('run.completed', data)],
    [`run:${runId}:failed`, (data) => onEvent('run.failed', data)],
  ]

  handlers.forEach(([event, handler]) => {
    client.on(event, handler)
  })

