{"content":"import { apiClient } from '../client'

export interface LoginCredentials {
  username: string
  password: string
}

export interface AuthToken {
  access_token: string
  token_type: string
  expires_in: number
}

export interface CurrentUser {
  id: string
  username: string
  email: string
  full_name?: string
  role: string
  is_active: boolean
  last_login?: string
  created_at: string
}

export const authApi = {
  /** POST /api/v1/auth/login */
  login: async (credentials: LoginCredentials): Promise<AuthToken> => {
    return apiClient.post<AuthToken>('/auth/login/json', credentials)
  },

  /** POST /api/v1/auth/login (form data) */
  loginForm: async (formData: FormData): Promise<AuthToken> => {
    return apiClient.post<AuthToken>('/auth/login', formData, {
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    })
  },

  /** GET /api/v1/auth/me */
  getMe: async (): Promise<CurrentUser> => {
    return apiClient.get<CurrentUser>('/auth/me')
  },

  /** POST /api/v1/auth/register */
  register: async (data: {
    username: string
    email: string
    password: string
    full_name?: string
    role?: string
  }): Promise<CurrentUser> => {
    return apiClient.post<CurrentUser>('/auth/register', data)
  },
}
